import { clockOfSessionMinute } from '../time';
import type { EventOutcome, EventSpec, Expr, Outcome, Win } from './ast';

const WEEKDAY_NAMES = ['', 'mon', 'tue', 'wed', 'thu', 'fri'];

export function renderWinBase(w: Win): string {
  switch (w.k) {
    case 'rth':
    case 'overnight':
    case 'session':
      return w.k;
    case 'prior':
      return (w.n === 1 ? 'prior' : `prior(${w.n})`) + (w.session ? '.session' : '');
    case 'or':
      return `or${w.n}`;
    case 'window':
      return `window(${clockOfSessionMinute(w.a)}, ${clockOfSessionMinute(w.b)})`;
    case 'bar':
      return `bar(${clockOfSessionMinute(w.t)}, ${w.len}m)`;
  }
}

/** Precedence for parenthesisation: or 1, and 2, not 3, relation 4, sum 5, product 6, unary 7, atom 8. */
function prec(e: Expr): number {
  switch (e.t) {
    case 'or':
      return 1;
    case 'and':
      return 2;
    case 'not':
      return 3;
    case 'cmp':
    case 'between':
    case 'in':
      return 4;
    case 'bin':
      return e.op === '+' || e.op === '-' ? 5 : 6;
    case 'neg':
      return 7;
    default:
      return 8;
  }
}

function child(e: Expr, parentPrec: number, rightOfMinusOrDiv = false): string {
  const p = prec(e);
  const s = renderExpr(e);
  return p < parentPrec || (p === parentPrec && rightOfMinusOrDiv) ? `(${s})` : s;
}

export function renderNumber(v: number): string {
  return String(v);
}

export function renderExpr(e: Expr): string {
  switch (e.t) {
    case 'num': {
      const n = renderNumber(e.value);
      if (e.unit === '%') return n + '%' + (e.of ? ' of ' + child(e.of, 8) : '');
      if (e.unit === 'pts') return n + ' pts';
      if (e.unit === 'ticks') return n + ' ticks';
      return n;
    }
    case 'win':
      return renderWinBase(e.win) + '.' + e.field;
    case 'gap':
    case 'weekday':
    case 'early_close':
      return e.t;
    case 'adr':
    case 'atr':
      return `${e.t}(${e.n})`;
    case 'wdname':
      return WEEKDAY_NAMES[e.day];
    case 'event': {
      if (!e.call) return e.kinds[0];
      const parts: string[] = [...e.kinds];
      if (e.named.includes('before')) parts.push(`before=${e.before}`);
      if (e.named.includes('after')) parts.push(`after=${e.after}`);
      return `event(${parts.join(', ')})`;
    }
    case 'days_since':
    case 'days_to':
      return `${e.t}(${e.kind})`;
    case 'at':
      return `at(${clockOfSessionMinute(e.time)})`;
    case 'neg':
      return '-' + child(e.x, 7);
    case 'bin': {
      const p = prec(e);
      return child(e.l, p) + ' ' + e.op + ' ' + child(e.r, p, e.op === '-' || e.op === '/');
    }
    case 'fn':
      return `${e.fn}(${e.args.map(renderExpr).join(', ')})`;
    case 'cmp':
      return child(e.l, 4) + ' ' + e.op + ' ' + child(e.r, 4);
    case 'between':
      return child(e.x, 5) + ' between ' + child(e.a, 5) + ' and ' + child(e.b, 5);
    case 'in':
      return child(e.x, 5) + (e.neg ? ' not in (' : ' in (') + e.list.map((x) => renderExpr(x)).join(', ') + ')';
    case 'and':
    case 'or': {
      const p = prec(e);
      return child(e.l, p) + ' ' + e.t + ' ' + child(e.r, p);
    }
    case 'not':
      return 'not ' + child(e.x, 3);
    case 'all':
      return 'all';
  }
}

export function renderEvent(ev: EventSpec): string {
  const level = renderExpr(ev.level);
  switch (ev.kind) {
    case 'touches':
      return 'touches ' + level;
    case 'trades_above':
      return 'trades above ' + level;
    case 'trades_below':
      return 'trades below ' + level;
    case 'closes_above':
    case 'closes_below':
      return (ev.kind === 'closes_above' ? 'closes above ' : 'closes below ') + level + (ev.barSize !== 1 ? ` on ${ev.barSize}m` : '');
  }
}

export function renderOutcome(o: Outcome): string {
  if (o.form === 'state') return renderExpr(o.expr);
  const ev = o as EventOutcome;
  let s = (ev.neg ? 'not ' : '') + renderEvent(ev.first);
  if (ev.seq && ev.second) s += ` ${ev.seq} ` + renderEvent(ev.second);
  if (ev.from) s += ` from ${clockOfSessionMinute(ev.from.time!)}`;
  if (ev.end) {
    if (ev.end.kind === 'within') s += ` within ${ev.end.minutes}m`;
    else if (ev.end.end) s += ` by ${ev.end.end}`;
    else s += ` by ${clockOfSessionMinute(ev.end.time!)}`;
  }
  return s;
}
